def main():
    BR.insert(21,'信息物理系统软件')
    rows=json.loads((CACHE/'candidates.json').read_text(encoding='utf-8'));result={}
    selections=[([r for r in rows if r['registry']=='embrapii_export'],BR,'focus_zh'),([r for r in rows if r['registry']=='jst_coinext'],JP,'title_zh'),([r for r in rows if r['registry'].startswith('africa')],AF,'title_zh'),([r for r in rows if r['registry']=='australia_crcp' and any(w in r['name'].lower() for w in ['energy','battery','batteries','hydrogen','solar','carbon','recycl','manufactur','mineral','mining','electric','steel','water','wind','bioenergy','copper','nickel','alumina'])],AU,'title_zh')]
    for group,labels,field in selections:
        assert len(group)==len(labels),(len(group),len(labels),field)
        for row,label in zip(group,labels):result[row['key']]={field:label,'source_title':row['name'],'translation_review_date':'2026-10-18'}
    (ROOT/'config/innovation_registry_translations.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('translated',len(result))
if __name__=='__main__':main()
